    [Fact]
    public async Task Pdf_with_broken_deflate_is_scanned_without_failing()
    {
        var scanner = BlueMailScanners.Create(new MalwareHashList(), new PatternRuleScanner());
        var act = async () => await scanner.ScanAsync(new MemoryStream(PdfBadDeflate), "fuzz.pdf");
        await act.Should().NotThrowAsync();
    }

    [Fact]
    public void Rrsig_signer_past_rdata_is_a_format_error() =>
        FluentActions.Invoking(() => DnsWire.Decode(DnsRrsig)).Should().Throw<DnsFormatException>();

    [Fact]
    public async Task Tar_with_an_impossible_size_is_scanned_without_failing()
    {
        var scanner = BlueMailScanners.Create(new MalwareHashList(), new PatternRuleScanner());
        var act = async () => await scanner.ScanAsync(new MemoryStream(TarHugeSize), "fuzz.tar");
        await act.Should().NotThrowAsync();
    }
